import { BaseScene } from '../../../base/baseScene';
import { LogToLocal, LogToServer } from '../../../base/decorators';

import type {
  ISettingCategoryOpenedParams,
  ISettingItemClickedParams,
  ISettingValueChangedParams,
  ISettingsOpenedParams,
  ISettingsSearchedParams,
} from '../types';

export class PageScene extends BaseScene {
  /**
   * Settings root opened. Fires once per mount, not on internal tab switches.
   */
  @LogToServer()
  @LogToLocal({ level: 'info' })
  public settingsOpened(params: ISettingsOpenedParams) {
    return params;
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public settingCategoryOpened(params: ISettingCategoryOpenedParams) {
    return params;
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public settingItemClicked(params: ISettingItemClickedParams) {
    return params;
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public settingValueChanged(params: ISettingValueChangedParams) {
    return params;
  }

  /**
   * In-settings search after the user stops typing. Never includes raw query
   * text — only length, result count, and the top result's stable id.
   */
  @LogToServer()
  @LogToLocal({ level: 'info' })
  public settingsSearched(params: ISettingsSearchedParams) {
    return params;
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public resetApp({
    reason,
  }: {
    reason: 'ManualResetFromSettings' | 'WrongPasscodeMaxAttempts';
  }) {
    return { reason };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public lockNow() {
    return {};
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public enterAddressBook() {
    return {};
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public addAddressBook({ network }: { network: string }) {
    return { network };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public removeAddressBook({ network }: { network: string }) {
    return { network };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public backup({ backupMethod }: { backupMethod: 'iCloud' | 'Google' }) {
    return { backupMethod };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public oneKeyLiteBackup() {
    return {};
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public oneKeyLiteBackupResult({ isSuccess }: { isSuccess: boolean }) {
    return { isSuccess };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public oneKeyLiteImportResult({ isSuccess }: { isSuccess: boolean }) {
    return { isSuccess };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public keyTagBackup() {
    return {};
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public keyTagImport() {
    return {};
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public keyTagImportResult({ isSuccess }: { isSuccess: boolean }) {
    return { isSuccess };
  }

  @LogToLocal({ level: 'info' })
  public clearDataStep(stepName: string) {
    return { stepName };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public clearData({
    action,
  }: {
    action: 'Cache' | 'Pending txn' | 'ResetApp';
  }) {
    return { action };
  }

  @LogToLocal({ level: 'info' })
  public restartApp(args?: { mode?: string; reason?: string }) {
    return {
      mode: args?.mode ?? 'unknown',
      reason: args?.reason ?? 'unknown',
    };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public addCustomRPC({ network }: { network: string }) {
    return { network };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public deleteCustomRPC({ network }: { network: string }) {
    return { network };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public turnOnCustomRPC({ network }: { network: string }) {
    return { network };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public turnOffCustomRPC({ network }: { network: string }) {
    return { network };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public settingsEnableBluetooth({ enabled }: { enabled: boolean }) {
    return { enabled };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public settingsEnableBTCFreshAddress({ enabled }: { enabled: boolean }) {
    return { enabled };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public enterChainListSearch() {
    return {};
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public chainListSearchPerformed({ keywords }: { keywords: string }) {
    return { keywords };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public chainListNetworkSelected({
    chainId,
    networkName,
  }: {
    chainId: string;
    networkName: string;
  }) {
    return { chainId, networkName };
  }

  @LogToServer()
  @LogToLocal({ level: 'info' })
  public chainListManualAdd() {
    return {};
  }

  // TODO(biologyAuth-debug): temporary log to diagnose biology auth visibility
  @LogToLocal({ level: 'info' })
  public biologyAuthDebug(tag: string, state: Record<string, unknown>) {
    return { tag, ...state };
  }
}
